import { getSupabase, escapeHtml as esc } from '../js/app-core.js';
import { requireAuth, signOut, createPatient, createDiet, fetchPatient, fetchPatientDiets, fetchDietWithMeals } from '../js/auth.js';
import { listClinical, addClinical, reviewClinical, listAppointments, addAppointment, listTasks, addTask, updateTask, uploadAttachment, getSignedAttachment } from '../js/clinical.js';
import { dateKey, subtractDays, datesInRange, waterSeries, assessmentSeries, coverage } from './metrics.mjs';
const db=getSupabase(), $=s=>document.querySelector(s), content=$('#page-content');
let profile, page='overview', patient=null, patients=[], selectedTab='summary', data={}, loading=0, offset=0, search='', favorites=new Set(), busy=false;
let range={start:subtractDays(dateKey(),29),end:dateKey()};
const tabNames={summary:'Resumo',anamnesis:'Anamnese',plan:'Plano alimentar',diary:'Diário e refeições',water:'Hidratação',assessment:'Avaliações e evolução',photos:'Fotos',checkin:'Atualizações',exercise:'Atividade física',documents:'Documentos',history:'Histórico'};
const kindNames={anamnesis:'Anamnese',assessment:'Avaliação',checkin:'Check-in',exercise:'Atividade física',note:'Nota',attachment:'Arquivo',consent:'Consentimento'};
const statusNames={draft:'Rascunho',submitted:'Enviado',reviewed:'Revisado',pending:'Pendente',completed:'Concluído',snoozed:'Adiado',scheduled:'Agendada',cancelled:'Cancelada',active:'Ativo',archived:'Arquivado'};
const fmt=d=>d?new Date(d.length===10?`${d}T12:00:00-03:00`:d).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'short',year:'numeric'}):'Não informado';
const time=d=>new Date(d).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
const initials=name=>(name||'').split(' ').filter(Boolean).map(s=>s[0]).slice(0,2).join('');
const empty=t=>`<div class="empty">${esc(t)}</div>`;
const pill=(text,warn=false)=>`<span class="pill ${warn?'attention':''}">${esc(text)}</span>`;
const stat=(label,value,sub)=>`<article class="stat"><label>${esc(label)}</label><div class="value">${esc(String(value))}</div><small>${esc(sub)}</small></article>`;
const field=(name,label,type='text',value='',required=false)=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(String(value??''))}" ${required?'required':''}></label>`;
const area=(name,label,value='')=>`<label class="field wide">${esc(label)}<textarea name="${name}">${esc(String(value??''))}</textarea></label>`;
const select=(name,label,options,value='')=>`<label class="field">${esc(label)}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4500);}
function errorView(error){content.innerHTML=`<section class="card"><h1>Não foi possível carregar</h1><p class="error">${esc(error.message)}</p><button data-action="refresh">Tentar novamente</button></section>`;}
async function query(q){const {data,error}=await q;if(error)throw error;return data||[];}
function patientOptions(){return patients.map(p=>[p.id,p.full_name]);}
function openEditor(title,fields,onSubmit){$('#editor-title').textContent=title;$('#editor-fields').innerHTML=fields;$('#editor-error').textContent='';$('#save-state').textContent='';$('#editor-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('#save-editor').disabled=true;$('#save-state').textContent='Salvando…';try{await onSubmit(new FormData(e.currentTarget));$('#editor').close();toast('Salvo com segurança.');await refresh();}catch(error){$('#editor-error').textContent=error.message;$('#save-state').textContent='Não foi salvo. Tente novamente.';}finally{busy=false;$('#save-editor').disabled=false;}};$('#editor').showModal();}
$('#close-editor').onclick=()=>{if(!busy)$('#editor').close();};
$('#logout').onclick=async()=>{await signOut();location.href='/admin/login/';};
$('#mobile-patients').onclick=()=>{$('#patient-rail').hidden=!$('#patient-rail').hidden;};
window.addEventListener('offline',()=>$('#connection').textContent='Você está sem conexão. Os registros só serão confirmados depois de salvos no servidor.');
window.addEventListener('online',()=>$('#connection').textContent='Conexão restabelecida. Atualize para consultar os dados mais recentes.');
$('#today').textContent=fmt(dateKey());
let searchTimer;$('#patient-search').oninput=e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{search=e.target.value.trim();loadPatients(true).catch(errorView);},250);};
$('#patient-filter').onchange=renderPatientList;
$('#more-patients').onclick=()=>loadPatients(false).catch(errorView);
$('#new-patient').onclick=createPatientForm;
async function loadPatients(reset=false){if(reset){offset=0;patients=[];}let q=db.from('profiles').select('id,user_id,full_name,username,created_at').eq('role','patient').order('full_name').range(offset,offset+49);if(search)q=q.ilike('full_name',`%${search.replace(/[%_]/g,'')}%`);const rows=await query(q);patients.push(...rows);offset+=rows.length;const activity=await db.rpc('patient_activity_summary',{p_since:new Date(Date.now()-7*86400000).toISOString()});if(activity.error)throw activity.error;data.activitySummary=activity.data||[];const ids=patients.map(p=>p.id);if(ids.length){const [plans,tasks]=await Promise.all([query(db.from('diets').select('patient_id').eq('status','active').in('patient_id',ids)),query(db.from('care_tasks').select('patient_id,status').in('patient_id',ids))]);data.activePatientIds=plans.map(p=>p.patient_id);data.taskPatientIds=tasks.filter(t=>!['completed','reviewed'].includes(t.status)).map(t=>t.patient_id);}$('#more-patients').hidden=rows.length<50;renderPatientList();}
function renderPatientList(){const filter=$('#patient-filter').value;const shown=patients.filter(p=>filter==='favorites'?favorites.has(p.id):filter==='inactive'?Number(data.activitySummary?.find(a=>a.patient_id===p.id)?.recent_count||0)===0:filter==='active'?(data.activePatientIds||[]).includes(p.id):filter==='attention'?(data.taskPatientIds||[]).includes(p.id):true);$('#patient-count').textContent=`${shown.length} paciente(s) carregado(s)`;$('#patient-list').innerHTML=shown.length?shown.map(p=>`<div class="patient-row ${patient?.id===p.id?'selected':''}"><button data-patient="${p.id}" aria-current="${patient?.id===p.id?'true':'false'}"><span class="avatar">${esc(initials(p.full_name))}</span><span>${esc(p.full_name)}<small>${(data.taskPatientIds||[]).includes(p.id)?'Pendência para revisar':esc(p.username)}</small></span></button><button class="star" data-star="${p.id}" aria-label="${favorites.has(p.id)?'Remover favorito':'Favoritar paciente'}" aria-pressed="${favorites.has(p.id)}">${favorites.has(p.id)?'★':'☆'}</button></div>`).join(''):empty('Nenhum paciente neste filtro.');}
$('#patient-list').onclick=e=>{const p=e.target.closest('[data-patient]'),s=e.target.closest('[data-star]');if(p)openPatient(p.dataset.patient);if(s){favorites.has(s.dataset.star)?favorites.delete(s.dataset.star):favorites.add(s.dataset.star);renderPatientList();saveFavorites().catch(error=>toast(error.message));}};
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
function markNavigation(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('selected',b.dataset.page===page));$('#breadcrumb').textContent=`CONSULTÓRIO / ${({overview:'VISÃO GERAL',patients:'PACIENTES',agenda:'AGENDA',tasks:'PENDÊNCIAS',content:'CONTEÚDOS',settings:'CONFIGURAÇÕES'})[page]}`;$('#patient-rail').hidden=page!=='patients';}
async function navigate(next){page=next;markNavigation();history.replaceState({},'',page==='patients'&&patient?`?patient=${patient.id}`:`?view=${page}`);try{await refresh();}catch(error){errorView(error);}}
async function refresh(){if(page==='patients'&&patient)return loadPatient(patient.id);if(page==='patients'){content.innerHTML=`<div class="heading"><div><span class="kicker">ACOMPANHAMENTO INDIVIDUAL</span><h1>Seu cuidado começa aqui.</h1><p class="subtitle">Selecione um paciente na lateral para abrir o prontuário.</p></div><button data-action="create-patient">+ Novo paciente</button></div>${empty('Busque um nome, escolha uma ficha e acompanhe os registros reais do paciente.')}`;return;}if(page==='overview')return overview();if(page==='agenda')return agenda();if(page==='tasks')return tasks();if(page==='content')return contents();if(page==='settings')return settings();}
async function openPatient(id){page='patients';selectedTab='summary';markNavigation();history.replaceState({},'',`?patient=${id}`);try{await loadPatient(id);}catch(error){errorView(error);}}
async function saveFavorites(){await query(db.from('admin_preferences').upsert({user_id:profile.user_id,payload:{favorites:[...favorites]}},{onConflict:'user_id'}).select());}
async function loadPatient(id){const request=++loading;content.innerHTML=empty('Carregando prontuário…');const [p,records,diets,appointments,tasks,water,meals,items,goals,previousWater,waterEvents,reports]=await Promise.all([fetchPatient(id),listClinical(id),fetchPatientDiets(id),listAppointments(id),listTasks(id),query(db.from('patient_water_logs').select('log_date,amount_ml,goal_ml,updated_at').eq('patient_id',id).gte('log_date',range.start).lte('log_date',range.end)),query(db.from('patient_meal_checks').select('check_date,meal_id,checked_at,diet_meals(name,diet_id)').eq('patient_id',id).gte('check_date',range.start).lte('check_date',range.end)),query(db.from('patient_item_checks').select('check_date,item_id,checked_at,diet_items(food_name,meal_id)').eq('patient_id',id).gte('check_date',range.start).lte('check_date',range.end)),query(db.from('patient_goals').select('*').eq('patient_id',id).order('valid_from',{ascending:false})),query(db.from('patient_water_logs').select('log_date,amount_ml,goal_ml').eq('patient_id',id).gte('log_date',subtractDays(range.start,datesInRange(range.start,range.end).length)).lt('log_date',range.start)),query(db.from('water_events').select('id,log_date,delta_ml,created_at').eq('patient_id',id).gte('log_date',range.start).lte('log_date',range.end)),query(db.from('meal_reports').select('meal_id,report_date,status,comment,updated_at,diet_meals(name)').eq('patient_id',id).gte('report_date',range.start).lte('report_date',range.end))]);if(request!==loading)return;patient=p;data={...data,records,diets,appointments,tasks,water,meals,items,goals,previousWater,waterEvents,reports,lastLogin:null};renderPatientList();renderPatient();const login=await db.rpc('patient_auth_activity',{p_patient:id});if(patient?.id===id){data.lastLogin=login.error?'Não disponível':login.data?time(login.data):'Sem login registrado';if($('#last-login'))$('#last-login').textContent=data.lastLogin;}}
function filters(){return `<div class="filters"><label>Período<select id="range-preset"><option value="custom">Personalizado</option><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option></select></label><label>De<input type="date" id="range-start" value="${range.start}"></label><label>Até<input type="date" id="range-end" value="${range.end}"></label><button class="secondary" data-action="apply-range">Aplicar</button><button class="secondary" data-action="refresh">↻ Atualizar</button></div>`;}
function renderPatient(){const anam=data.records.find(r=>r.kind==='anamnesis'&&r.status!=='draft');const next=data.appointments.find(a=>a.starts_at>new Date().toISOString()&&a.status!=='cancelled');const activities=[data.activitySummary?.find(a=>a.patient_id===patient.id)?.last_activity,...data.records.map(r=>r.created_at),...data.water.map(r=>r.updated_at),...data.meals.map(r=>r.checked_at),...data.items.map(r=>r.checked_at)].filter(Boolean).sort().reverse();content.innerHTML=`<div class="heading"><div class="patient-heading"><span class="avatar large">${esc(initials(patient.full_name))}</span><div><span class="kicker">PRONTUÁRIO INDIVIDUAL</span><h1>${esc(patient.full_name)}</h1><p class="subtitle">${esc(data.goals?.find(g=>g.valid_from<=dateKey())?.objective||anam?.payload?.objective||'Objetivo do acompanhamento ainda não registrado.')}</p></div></div><div class="actions"><button class="secondary" data-action="appointment">+ Consulta</button><button data-action="note">+ Nota privada</button><button class="secondary" data-action="goal">Metas</button><button class="secondary" data-action="reset-access">Acesso</button></div></div><div class="meta-grid"><div>Cadastro no sistema<strong>${fmt(patient.created_at)}</strong></div><div>Próxima consulta<strong>${next?time(next.starts_at):'Ainda não agendada'}</strong></div><div>Última atividade observada<strong>${activities[0]?time(activities[0]):'Sem registro'}</strong></div><div>Último login autenticado<strong id="last-login">${esc(data.lastLogin||'Não disponível nesta consulta')}</strong></div><div>Usuário de acesso<strong>${esc(patient.username)}</strong></div><div>Privacidade<strong>Notas privadas separadas dos relatos</strong></div></div><div class="tabs" role="tablist" aria-label="Prontuário">${Object.entries(tabNames).map(([key,label])=>`<button role="tab" aria-selected="${selectedTab===key}" class="${selectedTab===key?'active':''}" data-tab="${key}">${label}</button>`).join('')}</div><section id="patient-panel" role="tabpanel" aria-label="${tabNames[selectedTab]}">${patientPanel()}</section>`;const preset=$('#range-preset');if(preset)preset.onchange=()=>{if(preset.value!=='custom'){range={start:subtractDays(dateKey(),Number(preset.value)-1),end:dateKey()};loadPatient(patient.id).catch(errorView);}};hydrateImages();}
function chart(title,series,unit,bar=false){const chartId=title.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]/g,'-');const valid=series.filter(r=>r.value!==null);if(!valid.length)return `<section class="card"><h2>${esc(title)}</h2>${empty('Sem registros neste período. Ausência de informação não é zero.')}</section>`;const values=valid.flatMap(r=>[r.value,r.goal||0]);const max=Math.max(...values,1)*1.12;const width=640,height=190,left=42,bottom=155,x=i=>bar?left+(i+.5)*(width-left-10)/series.length:series.length<2?width/2:left+10+(new Date(series[i].date)-new Date(series[0].date))/Math.max(1,new Date(series.at(-1).date)-new Date(series[0].date))*(width-left-30),y=v=>bottom-v/max*130;const points=series.map((r,i)=>r.value===null?null:`${x(i)},${y(r.value)}`);let paths=[],segment=[];for(const p of [...points,null]){if(p)segment.push(p);else if(segment.length){paths.push(segment.join(' '));segment=[];}}const svg=`<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(title)} em ${esc(unit)}. Valores disponíveis na tabela abaixo."><line class="axis" x1="${left}" y1="${bottom}" x2="${width}" y2="${bottom}"/><text x="0" y="25">${Math.round(max)}</text><text x="15" y="${bottom}">0</text>${bar?'':paths.map(p=>`<polyline class="trace" points="${p}"/>`).join('')}${series.map((r,i)=>r.value===null?'':`<a href="#record-${chartId}-${r.id||r.date}" aria-label="${fmt(r.date)}: ${r.value.toFixed(1)} ${unit}"><title>${fmt(r.date)}: ${r.value.toFixed(1)} ${unit}</title>${bar?`<rect class="bar" x="${x(i)-Math.max(2,220/series.length)}" y="${y(r.value)}" width="${Math.max(4,440/series.length)}" height="${bottom-y(r.value)}" rx="3"/>`:`<circle class="point" cx="${x(i)}" cy="${y(r.value)}" r="4"/>`}${r.goal?`<line class="goal" x1="${x(i)-12}" x2="${x(i)+12}" y1="${y(r.goal)}" y2="${y(r.goal)}"/>`:''}</a>`).join('')}<text x="${left}" y="183">${fmt(series[0].date)}</text><text text-anchor="end" x="630" y="183">${fmt(series.at(-1).date)}</text></svg>`;return `<section class="card"><div class="card-head"><h2>${esc(title)}</h2>${pill(unit)}</div>${svg}<div class="legend"><span>Registrado</span>${bar?'<span class="goal">Meta registrada no dia</span>':''}</div><details open><summary>Valores e origem dos registros</summary><div class="table-wrap"><table><thead><tr><th>Data</th><th>${esc(unit)}</th>${bar?'<th>Meta (ml)</th>':'<th>Origem</th>'}</tr></thead><tbody>${series.map(r=>`<tr id="record-${chartId}-${r.id||r.date}" tabindex="-1"><td>${fmt(r.date)}</td><td>${r.value===null?'Sem registro':r.value.toLocaleString('pt-BR',{maximumFractionDigits:2})}</td><td>${bar?(r.goal??'Não registrada'):esc(r.raw?.payload?.source||'Informada na avaliação')}</td></tr>`).join('')}</tbody></table></div></details></section>`;}
function recordsFor(kind){return data.records.filter(r=>r.kind===kind);}
function recordCards(records){return records.length?records.map(r=>`<article class="item" id="clinical-${r.id}"><div class="card-head"><strong>${esc(kindNames[r.kind]||r.kind)} · ${fmt(r.occurred_at)}</strong>${pill(statusNames[r.status]||r.status,r.status==='submitted')}</div><p>Versão ${r.version} · ${r.created_by===patient.id?'Informado pelo paciente':'Registrado pela profissional'} · ${r.visibility==='private'?'Privado da nutricionista':'Compartilhado com o paciente'} · Lançado ${time(r.created_at)}</p>${payloadView(r.payload)}<div class="item-actions">${r.status!=='reviewed'?`<button class="secondary" data-review="${r.id}">Marcar revisado</button>`:''}${r.kind==='anamnesis'?`<button class="secondary" data-edit-anamnesis="${r.id}">Criar nova versão</button>`:''}</div></article>`).join(''):empty('Ainda não há registros. Quando forem enviados, aparecerão aqui com data e autoria.');}
const labels={objective:'Objetivo',routine:'Rotina',preferences:'Preferências',restrictions:'Restrições',allergies:'Alergias',history:'Histórico informado',medications:'Medicamentos relatados',supplements:'Suplementos relatados',sleep:'Sono',exercise:'Atividade física',habits:'Hábitos alimentares',difficulties:'Dificuldades',reported_by:'Origem do relato',weight_kg:'Peso (kg)',height_cm:'Altura (cm)',measurements:'Medidas (cm)',source:'Origem',method:'Método de avaliação',hunger:'Fome (1–5)',satiety:'Saciedade (1–5)',energy:'Energia (1–5)',sleep_hours:'Horas de sono',difficulty:'Dificuldade',achievement:'Conquista',notes:'Observações',help_requested:'Pediu ajuda',modality:'Modalidade',duration_minutes:'Duração (min)',frequency:'Frequência',text:'Registro',filename:'Arquivo',position:'Posição',description:'Descrição',body_composition:'Composição corporal informada'};
function payloadView(payload){return Object.entries(payload||{}).filter(([key])=>!['path','bytes','mime','visibility','measured_at','scale_max','template'].includes(key)).map(([key,value])=>`<p><strong>${esc(payload.template?.fields?.find(f=>f.key===key)?.label||labels[key]||key)}:</strong> ${esc(typeof value==='object'?Object.entries(value||{}).map(([k,v])=>`${k}: ${v}`).join(' · '):typeof value==='boolean'?(value?'Sim':'Não'):String(value||'Não informado'))}</p>`).join('');}
function patientPanel(){const filtered=data.records.filter(r=>dateKey(new Date(r.occurred_at))>=range.start&&dateKey(new Date(r.occurred_at))<=range.end);if(selectedTab==='summary'){const series=waterSeries(data.water,range.start,range.end,data.goals),cov=coverage(series),unreviewed=data.records.filter(r=>r.status==='submitted'&&r.created_by===patient.id);return `${filters()}<div class="stats">${stat('Hidratação registrada',`${cov.count}/${cov.total}`,'dias com registro no período')}${stat('Relatos de refeições',new Set([...data.meals.map(r=>r.meal_id+':'+r.check_date),...(data.reports||[]).map(r=>r.meal_id+':'+r.report_date)]).size,'checks enviados pelo paciente')}${stat('Atualizações para revisar',unreviewed.length,'relatos ainda não revisados')}${stat('Avaliações',recordsFor('assessment').length,'medições efetivamente informadas')}</div><div class="grid"><div>${chart('Hidratação no período',series,'ml',true)}${chart('Evolução do peso',assessmentSeries(filtered,'weight_kg'),'kg')}</div><div><section class="card"><h2>Próxima ação de cuidado</h2>${taskList(data.tasks.filter(t=>!['completed','reviewed'].includes(t.status)))}<button class="secondary" data-action="task">+ Criar tarefa</button></section><section class="card"><h2>Atualizações recentes</h2>${recordCards(data.records.slice(0,3))}</section>${consultationSummary()}</div></div>`;}if(selectedTab==='water'){const series=waterSeries(data.water,range.start,range.end,data.goals),cov=coverage(series);return `${filters()}<p class="notice">Cobertura: ${cov.count} de ${cov.total} dias (${cov.percent}%). As metas são as registradas em cada dia. Dias sem informação não entram como zero.</p>${chart('Consumo diário de água',series,'ml',true)}${waterComparison()}${waterEventTable()}`;}if(selectedTab==='assessment'){return `${filters()}<div class="heading"><p class="subtitle">Medições com data, origem e autoria. O IMC é peso (kg) ÷ altura (m)², sem interpretação automática.</p><button data-action="assessment">+ Nova avaliação</button></div>${chart('Peso',assessmentSeries(filtered,'weight_kg'),'kg')}${chart('IMC',assessmentSeries(filtered,'bmi'),'kg/m²')}<section class="card"><h2>Medidas corporais</h2><label class="field">Medida<select id="measurement">${[...new Set(filtered.flatMap(r=>Object.keys(r.payload.measurements||{})))].map(k=>`<option>${esc(k)}</option>`).join('')}</select></label><div id="measure-chart">${empty('Selecione uma medida registrada para comparar as avaliações.')}</div></section><section class="card"><h2>Avaliações registradas</h2>${recordCards(recordsFor('assessment'))}</section>`;}if(selectedTab==='anamnesis')return `<div class="heading"><p class="subtitle">Rascunhos e versões anteriores são preservados. Registre a origem de cada relato.</p><button data-action="anamnesis">+ Nova anamnese</button></div><section class="card">${recordCards(recordsFor('anamnesis'))}</section>`;if(selectedTab==='plan')return `<div class="heading"><p class="subtitle">Plano ativo, rascunhos e histórico de versões.</p><button data-action="diet">+ Novo plano</button></div><section class="card">${data.diets.length?data.diets.map(d=>`<article class="item"><div class="card-head"><strong>${esc(d.title)}</strong>${pill(statusNames[d.status]||d.status)}</div><p>Início informado: ${fmt(d.start_date)} · Atualizado ${fmt(d.updated_at)}</p><div class="item-actions"><a class="link-btn" href="/admin/diet/?patient=${patient.id}&diet=${d.id}">Abrir editor</a><button class="secondary" data-preview-diet="${d.id}">Prévia / PDF</button></div></article>`).join(''):empty('Nenhum plano cadastrado.')}</section><a class="link-btn" href="/admin/banco/?id=${patient.id}">Consultar Banco de Pontos</a>`;if(selectedTab==='diary')return `${filters()}<p class="notice">Checks são relatos do paciente. Sem check significa “sem registro”; não comprova que a refeição não aconteceu. Os planos antigos não têm vigência completa registrada, por isso não calculamos percentuais históricos a partir do plano atual.</p><section class="card"><h2>Calendário de constância dos registros</h2>${recordCalendar()}</section><section class="card"><h2>Matriz de refeições registradas</h2>${mealMatrix()}</section><section class="card"><h2>Alimentos registrados</h2>${data.items.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Alimento</th><th>Relato</th></tr></thead><tbody>${data.items.map(r=>`<tr><td>${fmt(r.check_date)}</td><td>${esc(r.diet_items?.food_name||'Item histórico')}</td><td>✓ Registrado</td></tr>`).join('')}</tbody></table></div>`:empty('Sem registros de alimentos no período.')}</section>`;if(selectedTab==='checkin')return `<div class="heading"><p class="subtitle">Fome, saciedade, sono e dificuldades são autorrelatos.</p><button data-action="checkin">+ Registrar atualização</button></div>${filters()}${checkinCharts(filtered)}<section class="card">${recordCards(recordsFor('checkin'))}</section>`;if(selectedTab==='exercise')return `<div class="heading"><p class="subtitle">Atividade física autorrelatada, separada do uso da plataforma.</p><button data-action="exercise">+ Registrar atividade</button></div><section class="card">${recordCards(recordsFor('exercise'))}</section>`;if(selectedTab==='photos'||selectedTab==='documents'){const photos=selectedTab==='photos';const records=recordsFor('attachment').filter(r=>photos?r.payload.category==='photo':r.payload.category!=='photo');return `<div class="heading"><p class="subtitle">Arquivos privados. Links de acesso expiram em dois minutos.</p><button data-action="${photos?'photo':'document'}">+ Enviar ${photos?'foto':'documento'}</button></div>${photos&&records.length>=2?`<section class="card"><h2>Comparar avaliações</h2><div class="form-grid">${select('photo-a','Primeira foto',records.map(r=>[r.id,`${fmt(r.occurred_at)} · ${r.payload.position||'Sem posição'}`]))}${select('photo-b','Segunda foto',records.map(r=>[r.id,`${fmt(r.occurred_at)} · ${r.payload.position||'Sem posição'}`]),records[1].id)}</div><button data-action="compare-photos">Comparar</button><div id="comparison" class="photo-grid"></div></section>`:''}<section class="card ${photos?'photo-grid':''}">${records.length?records.map(r=>`<article class="item photo-card">${photos?`<img data-private-image="${esc(r.payload.path)}" alt="Foto ${esc(r.payload.position||'de acompanhamento')} de ${fmt(r.occurred_at)}" loading="lazy">`:''}<strong>${esc(r.payload.filename||r.payload.name||'Arquivo')}</strong><p>${fmt(r.occurred_at)} · ${esc(r.payload.position||r.payload.description||'')}</p><button class="secondary" data-file="${esc(r.payload.path)}">Abrir arquivo</button>${r.status!=='reviewed'?` <button class="secondary" data-review="${r.id}">Revisado</button>`:''}</article>`).join(''):empty('Nenhum arquivo enviado ainda.')}</section>`;}return `<div class="heading"><p class="subtitle">Linha do tempo de registros, planos e consultas. As notas privadas são visíveis apenas à equipe.</p><button class="secondary" data-action="export">Exportar registros consultados</button></div><section class="card"><div class="timeline">${historyTimeline()}</div></section>`;}
function mealMatrix(){const dates=datesInRange(range.start,range.end);const meals=[...new Map([...data.meals,...(data.reports||[])].map(r=>[r.meal_id,r.diet_meals?.name||'Refeição histórica'])).entries()];if(!meals.length)return empty('Nenhum relato de refeição no período. Os dias permanecem sem registro.');const cell=(id,date)=>{const report=(data.reports||[]).find(r=>r.meal_id===id&&r.report_date===date);if(report)return {text:({done:'✓ Realizada',partial:'◐ Parcial',skipped:'× Não realizada'})[report.status],comment:report.comment||'',reported:true};return data.meals.some(r=>r.meal_id===id&&r.check_date===date)?{text:'✓ Relatada',comment:'Check legado do paciente',reported:true}:{text:'— Sem registro',comment:'',reported:false};};return `<div class="table-wrap"><table><thead><tr><th>Refeição</th>${dates.map(d=>`<th>${fmt(d)}</th>`).join('')}</tr></thead><tbody>${meals.map(([id,name])=>`<tr><th>${esc(name)}</th>${dates.map(d=>{const c=cell(id,d);return `<td class="${c.reported?'matrix-check':''}" title="${esc(c.comment)}">${c.text}${c.comment?`<details><summary>Relato</summary>${esc(c.comment)}</details>`:''}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;}
async function hydrateImages(){await Promise.all([...document.querySelectorAll('[data-private-image]')].map(async img=>{try{img.src=await getSignedAttachment(img.dataset.privateImage);}catch{img.alt+=' · Não foi possível carregar. Tente atualizar.';}}));}
function taskList(rows){return rows.length?rows.map(t=>`<article class="item"><strong>${esc(t.title)}</strong><p>${esc(t.reason||'')}<br>${t.due_at?'Prazo: '+time(t.due_at):'Sem prazo definido'} · ${esc(statusNames[t.status]||t.status)}</p><div class="item-actions">${t.patient_id?`<button class="secondary" data-open-patient="${t.patient_id}">Abrir paciente</button>`:''}${!['completed','reviewed'].includes(t.status)?`<button class="secondary" data-task-done="${t.id}">Marcar revisado</button><button class="secondary" data-task-snooze="${t.id}">Adiar 1 dia</button>`:''}</div></article>`).join(''):empty('Nenhuma pendência registrada.');}
async function overview(){const [all,plans,appointments,tasks,updates]=await Promise.all([query(db.from('profiles').select('id,full_name').eq('role','patient')),query(db.from('diets').select('patient_id').eq('status','active')),listAppointments(),listTasks(),query(db.from('clinical_records').select('id,patient_id,kind,created_at,payload').eq('status','submitted').order('created_at',{ascending:false}).limit(30))]);data.activePatientIds=plans.map(p=>p.patient_id);data.taskPatientIds=tasks.filter(t=>!['completed','reviewed'].includes(t.status)).map(t=>t.patient_id);renderPatientList();const upcoming=appointments.filter(a=>a.starts_at>=new Date().toISOString()&&a.status!=='cancelled');const pending=tasks.filter(t=>!['completed','reviewed'].includes(t.status)&&(!t.snoozed_until||t.snoozed_until<new Date().toISOString()));const names=new Map(all.map(p=>[p.id,p.full_name]));content.innerHTML=`<div class="heading"><div><span class="kicker">CUIDADO CONTÍNUO, EM UM SÓ LUGAR</span><h1>Olá, ${esc(profile.full_name.split(' ')[0])}.</h1><p class="subtitle">Uma visão clara do acompanhamento e do que merece sua atenção.</p></div><button data-action="create-patient">+ Novo paciente</button></div><div class="stats">${stat('Pacientes cadastrados',all.length,'contas de pacientes preservadas')}${stat('Com plano ativo',new Set(plans.map(p=>p.patient_id)).size,'pacientes em acompanhamento alimentar')}${stat('Próximas consultas',upcoming.length,'agendamentos futuros')}${stat('Pendências abertas',pending.length,'ações para acompanhar')}</div><div class="grid"><section class="card"><div class="card-head"><h2>Sua central de atenção</h2>${pill('Acompanhamento, sem rótulos')}</div>${taskList(pending)}<button class="secondary" data-action="task">+ Criar tarefa</button></section><div><section class="card"><div class="card-head"><h2>Próximos encontros</h2><button class="secondary" data-action="appointment">+ Agendar</button></div>${upcoming.length?upcoming.slice(0,5).map(a=>`<article class="item"><strong>${esc(names.get(a.patient_id)||'Paciente')}</strong><p>${time(a.starts_at)}</p><button class="secondary" data-open-patient="${a.patient_id}">Preparar consulta</button></article>`).join(''):empty('Nenhuma consulta futura agendada.')}</section><section class="card"><h2>Atualizações para revisar</h2>${updates.length?updates.slice(0,8).map(r=>`<article class="item"><strong>${esc(names.get(r.patient_id)||'Paciente')}</strong><p>${esc(kindNames[r.kind]||r.kind)} · ${time(r.created_at)}</p><button class="secondary" data-open-patient="${r.patient_id}">Abrir registro</button></article>`).join(''):empty('Sem novas atualizações aguardando revisão.')}</section></div></div>`;}
async function agenda(){const rows=await listAppointments();content.innerHTML=`<div class="heading"><div><span class="kicker">AGENDA</span><h1>Encontros que dão continuidade.</h1><p class="subtitle">Horários exibidos em America/Sao_Paulo.</p></div><button data-action="appointment">+ Agendar consulta</button></div><section class="card">${rows.length?rows.map(a=>`<article class="item"><div class="card-head"><strong>${esc(patients.find(p=>p.id===a.patient_id)?.full_name||'Paciente')}</strong>${pill(statusNames[a.status]||a.status)}</div><p>${time(a.starts_at)}${a.ends_at?' — '+time(a.ends_at):''}</p><p>${esc(a.notes||'')}</p><div class="item-actions"><button class="secondary" data-open-patient="${a.patient_id}">Abrir prontuário</button>${a.status==='scheduled'?`<button class="secondary" data-complete-appointment="${a.id}">Marcar realizada</button><button class="secondary" data-cancel-appointment="${a.id}">Cancelar consulta</button>`:''}</div></article>`).join(''):empty('Sua agenda ainda está vazia. Crie o primeiro encontro.')}</section>`;}
async function tasks(){const rows=await listTasks();const notices=await query(db.from('care_notifications').select('*').order('created_at',{ascending:false}).limit(50));content.innerHTML=`<div class="heading"><div><span class="kicker">ACOMPANHAMENTO</span><h1>Mensagens e pendências</h1><p class="subtitle">Avisos internos e tarefas com contexto para a próxima ação.</p></div><button data-action="task">+ Criar tarefa</button></div><div class="grid"><section class="card"><h2>Tarefas</h2>${taskList(rows)}</section><section class="card"><h2>Notificações internas</h2>${notices.length?notices.map(n=>`<article class="item"><strong>${esc(n.title)}</strong><p>${esc(n.body||'')}</p><p>${time(n.created_at)}</p><button class="secondary" data-open-patient="${n.patient_id}">Abrir paciente</button></article>`).join(''):empty('Nenhuma notificação gerada ainda.')}</section></div>`;}
function contents(){content.innerHTML=`<span class="kicker">BIBLIOTECA DO CONSULTÓRIO</span><h1>Conteúdos e desafios</h1><p class="subtitle">Acesso às ferramentas já disponíveis, preservando os registros.</p><div class="grid"><section class="card"><h2>Desafios</h2><p class="subtitle">Gerencie os desafios existentes e seus participantes.</p><a class="link-btn" href="/admin/desafios/">Abrir desafios</a></section><section class="card"><h2>Guias e Banco de Pontos</h2><p class="subtitle">Os guias continuam disponíveis na área do paciente. Consulte o Banco de Pontos pela ficha individual.</p><button class="secondary" data-action="patients">Selecionar paciente</button></section></div>`;}
async function settings(){const [rules,runs,templates]=await Promise.all([query(db.from('automation_rules').select('*').order('created_at')),query(db.from('automation_runs').select('*').order('created_at',{ascending:false}).limit(30)),query(db.from('checkin_templates').select('*').order('created_at',{ascending:false}))]);content.innerHTML=`<div class="heading"><div><span class="kicker">CONFIGURAÇÕES</span><h1>Uma rotina mais leve.</h1><p class="subtitle">Automações internas executadas no servidor, mesmo com o navegador fechado.</p></div><a class="link-btn" href="/admin/login/security/">Segurança e autenticação em dois fatores</a></div><section class="card"><div class="card-head"><h2>Formulários de check-in</h2><button data-action="checkin-template">+ Novo formulário</button></div>${templates.length?templates.map(t=>`<article class="item"><strong>${esc(t.name)}</strong> ${pill(t.active?'Disponível ao paciente':'Inativo')}<p>${(t.fields||[]).length} perguntas</p><button class="secondary" data-toggle-template="${t.id}" data-enabled="${t.active}">${t.active?'Desativar':'Ativar'}</button></article>`).join(''):empty('Nenhum formulário configurado.')}</section><section class="card"><h2>Central de automações</h2><p class="notice">E-mail, WhatsApp e push não estão configurados. As regras abaixo geram somente notificações e tarefas internas. Nenhum envio externo é simulado.</p>${rules.length?rules.map(r=>`<article class="item"><div class="card-head"><strong>${esc(r.title)}</strong>${pill(r.enabled?'Ativada':'Desativada')}</div><p>${esc(r.kind)}</p><div class="item-actions"><button class="secondary" data-toggle-rule="${r.id}" data-enabled="${r.enabled}">${r.enabled?'Desativar':'Ativar'}</button><button class="secondary" data-edit-rule="${r.id}" data-config="${esc(JSON.stringify(r.config))}">Editar parâmetros</button></div></article>`).join(''):empty('Nenhuma regra cadastrada no servidor.')}</section><section class="card"><h2>Histórico de execução</h2>${runs.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Resultado</th><th>Tentativas</th><th>Detalhe</th></tr></thead><tbody>${runs.map(r=>`<tr><td>${time(r.created_at)}</td><td>${esc(r.status)}</td><td>${r.attempts}</td><td>${esc(r.error||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('Ainda não há execuções. A ativação de uma regra permite processamento pelo agendador do servidor.')}</section>`;}
function createPatientForm(){openEditor('Novo paciente',field('full_name','Nome completo','text','',true)+field('username','Usuário','text','',true)+field('password','Senha inicial (mínimo 12 caracteres)','password','',true)+area('notes','Observação administrativa'),async fd=>{if(fd.get('password').length<12)throw Error('Use pelo menos 12 caracteres.');await createPatient(Object.fromEntries(fd));await loadPatients(true);});}
function appointmentForm(){openEditor('Agendar consulta',select('patient_id','Paciente',patientOptions(),patient?.id)+field('starts_at','Início — horário de São Paulo','datetime-local','',true)+field('ends_at','Término — horário de São Paulo','datetime-local','',true)+area('notes','Orientação compartilhada'),async fd=>{const start=new Date(fd.get('starts_at')+'-03:00').toISOString(),end=new Date(fd.get('ends_at')+'-03:00').toISOString();if(end<=start)throw Error('O término deve ser depois do início.');await addAppointment({patient_id:fd.get('patient_id'),starts_at:start,ends_at:end,status:'scheduled',notes:fd.get('notes')});});}
function taskForm(){openEditor('Nova tarefa de acompanhamento',select('patient_id','Paciente',patientOptions(),patient?.id)+field('title','Próxima ação','text','',true)+area('reason','Motivo e registros que sustentam a tarefa')+field('due_at','Prazo — horário de São Paulo','datetime-local'),async fd=>{await addTask({patient_id:fd.get('patient_id'),title:fd.get('title'),reason:fd.get('reason'),status:'pending',due_at:fd.get('due_at')?new Date(fd.get('due_at')+'-03:00').toISOString():null});});}
function assessmentForm(){openEditor('Registrar avaliação',`<div class="form-grid">${field('date','Data da medição','date',dateKey(),true)}${select('source','Origem',[['Profissional','Medição pela profissional'],['Paciente','Informada pelo paciente'],['Exame','Exame enviado']])}${field('weight_kg','Peso (kg)','number')}${field('height_cm','Altura (cm)','number')}${field('waist','Cintura (cm)','number')}${field('hip','Quadril (cm)','number')}${field('measurement_name','Outra medida: nome')}${field('measurement_value','Outra medida (cm)','number')}${field('method','Método da avaliação')}${area('notes','Observações')}</div><p class="notice">A data de lançamento e o responsável são registrados automaticamente. Nenhuma composição corporal é estimada.</p>`,async fd=>{const payload={source:fd.get('source'),method:fd.get('method'),notes:fd.get('notes'),measurements:{}};for(const k of ['weight_kg','height_cm'])if(fd.get(k)!==''){const v=Number(fd.get(k));if(!Number.isFinite(v)||v<=0)throw Error('Peso e altura devem ser positivos.');payload[k]=v;}for(const [key,name]of [['waist','Cintura'],['hip','Quadril']])if(fd.get(key)!==''){const v=Number(fd.get(key));if(v<=0)throw Error('Medidas devem ser positivas.');payload.measurements[name]=v;}if(fd.get('measurement_name')&&fd.get('measurement_value')){const v=Number(fd.get('measurement_value'));if(!Number.isFinite(v)||v<=0)throw Error('A medida adicional deve ser positiva.');payload.measurements[fd.get('measurement_name')]=v;}if(!payload.weight_kg&&!Object.keys(payload.measurements).length)throw Error('Informe peso ou pelo menos uma medida.');await addClinical(patient.id,'assessment',payload,{occurredAt:fd.get('date')+'T12:00:00-03:00'});});$('#editor').querySelectorAll('[type=number]').forEach(i=>{i.step='0.1';i.min='0.1';});}
function anamnesisForm(previous){const values=previous?.payload||{};openEditor(previous?'Nova versão da anamnese':'Anamnese',`<p class="notice">Cada salvamento cria uma versão preservada. Identifique se o conteúdo foi relatado pelo paciente ou registrado pela profissional.</p>${select('reported_by','Origem',[['Paciente','Informado pelo paciente'],['Profissional','Registrado pela profissional']],values.reported_by)}${select('status','Estado',[['draft','Salvar rascunho'],['reviewed','Concluir revisão']],previous?.status||'draft')}<div class="form-grid">${['objective','routine','preferences','restrictions','allergies','history','sleep','exercise','habits','difficulties'].map(k=>area(k,labels[k],values[k]||'')).join('')}<label class="check-field wide"><input type="checkbox" id="has-medications" ${values.medications||values.supplements?'checked':''}>Relatou uso de medicamentos ou suplementos</label><div id="medication-details" class="wide">${area('medications',labels.medications,values.medications||'')}${area('supplements',labels.supplements,values.supplements||'')}</div></div>`,async fd=>{const payload=Object.fromEntries(fd);delete payload.status;await addClinical(patient.id,'anamnesis',payload,{status:fd.get('status'),parentId:previous?.id,version:(previous?.version||0)+1});});const medicationToggle=$('#has-medications');$('#medication-details').hidden=!medicationToggle.checked;medicationToggle.onchange=()=>$('#medication-details').hidden=!medicationToggle.checked;}
function checkinForm(){openEditor('Registrar relato do check-in',`<div class="form-grid">${field('date','Data do relato','date',dateKey(),true)}${field('hunger','Fome (1 a 5)','number')}${field('satiety','Saciedade (1 a 5)','number')}${field('energy','Energia (1 a 5)','number')}${field('sleep_hours','Horas de sono','number')}${area('difficulty','Dificuldade relatada')}${area('achievement','Conquista relatada')}${area('notes','Observações')}</div><label class="check-field"><input type="checkbox" name="help_requested">Paciente pediu ajuda</label>`,async fd=>{const payload=Object.fromEntries(fd);delete payload.date;for(const k of ['hunger','satiety','energy','sleep_hours']){if(payload[k]!==''){payload[k]=Number(payload[k]);if(payload[k]<(k==='sleep_hours'?0:1)||payload[k]>(k==='sleep_hours'?24:5))throw Error('Revise os valores informados.');}else delete payload[k];}payload.scale_max=5;payload.help_requested=fd.has('help_requested');await addClinical(patient.id,'checkin',payload,{occurredAt:fd.get('date')+'T12:00:00-03:00',status:'reviewed'});});$('#editor').querySelectorAll('[type=number]').forEach(i=>{i.step=i.name==='sleep_hours'?'0.5':'1';i.min=i.name==='sleep_hours'?'0':'1';i.max=i.name==='sleep_hours'?'24':'5';});}
function exerciseForm(){openEditor('Atividade física autorrelatada',field('date','Data','date',dateKey(),true)+field('modality','Modalidade','text','',true)+field('duration_minutes','Duração em minutos','number','',true)+field('frequency','Frequência relatada')+area('notes','Observações'),async fd=>{if(Number(fd.get('duration_minutes'))<=0)throw Error('Informe uma duração positiva.');await addClinical(patient.id,'exercise',{modality:fd.get('modality'),duration_minutes:Number(fd.get('duration_minutes')),frequency:fd.get('frequency'),notes:fd.get('notes')},{occurredAt:fd.get('date')+'T12:00:00-03:00',status:'reviewed'});});}
function attachmentForm(photo){openEditor(photo?'Enviar foto de acompanhamento':'Enviar documento',field('file','Arquivo privado (JPG, PNG, WebP ou PDF; até 20 MB)','file','',true)+field('date','Data da foto ou documento','date',dateKey(),true)+(photo?select('position','Posição',[['frente','Frente'],['costas','Costas'],['lateral','Lateral'],['outra','Outra']]):'')+area('description','Descrição')+select('visibility','Acesso',[['shared','Profissional e paciente'],['private','Somente profissional']]),async fd=>{const file=fd.get('file');if(photo&&!file.type.startsWith('image/'))throw Error('Para acompanhamento fotográfico, escolha uma imagem.');await uploadAttachment(patient.id,file,{category:photo?'photo':'document',position:fd.get('position')||'',description:fd.get('description'),visibility:fd.get('visibility'),measured_at:fd.get('date')+'T12:00:00-03:00'});});}
async function previewDiet(id){const diet=await fetchDietWithMeals(id);openEditor('Prévia do plano',`<div id="print-plan"><h2>${esc(diet.title)}</h2><p>${esc(patient.full_name)} · ${fmt(diet.start_date)}</p>${diet.meals.map(m=>`<article class="item"><h3>${esc(m.name)} ${esc(m.scheduled_time||'')}</h3>${m.diet_items.map(i=>`<p>${esc(i.food_name)} — ${esc([i.quantity,i.unit].filter(Boolean).join(' '))}${i.notes?' · '+esc(i.notes):''}${i.substitutions?'<br>Substituições: '+esc(i.substitutions):''}</p>`).join('')}</article>`).join('')}<p>${esc(diet.notes||'')}</p></div><button type="button" id="print-diet">Imprimir / salvar em PDF</button>`,async()=>{});$('#save-editor').hidden=true;$('#print-diet').onclick=()=>window.print();$('#editor').addEventListener('close',()=>$('#save-editor').hidden=false,{once:true});}
async function comparePhotos(){const ids=[$('[name=photo-a]').value,$('[name=photo-b]').value];const records=ids.map(id=>data.records.find(r=>r.id===id));$('#comparison').innerHTML=records.map(r=>`<figure><img data-private-image="${esc(r.payload.path)}" alt="${esc(r.payload.position||'Foto')} em ${fmt(r.occurred_at)}"><figcaption>${fmt(r.occurred_at)} · ${esc(r.payload.position||'')}</figcaption></figure>`).join('');await hydrateImages();}
async function applyAction(action){if(action==='checkin-template')return templateForm();if(action==='reset-access')return accessForm();if(action==='goal')return goalForm();if(action==='refresh')return refresh();if(action==='patients')return navigate('patients');if(action==='create-patient')return createPatientForm();if(action==='appointment')return appointmentForm();if(action==='task')return taskForm();if(action==='assessment')return assessmentForm();if(action==='anamnesis')return anamnesisForm();if(action==='checkin')return checkinForm();if(action==='exercise')return exerciseForm();if(action==='photo'||action==='document')return attachmentForm(action==='photo');if(action==='compare-photos')return comparePhotos();if(action==='note')return openEditor('Nota privada da nutricionista',area('text','Nota — não será mostrada ao paciente'),async fd=>{if(!fd.get('text').trim())throw Error('Escreva uma nota antes de salvar.');await addClinical(patient.id,'note',{text:fd.get('text')},{visibility:'private',status:'reviewed'});});if(action==='diet'){const id=await createDiet(patient.id,'Plano alimentar');location.href=`/admin/diet/?patient=${patient.id}&diet=${id}`;}if(action==='apply-range'){const start=$('#range-start').value,end=$('#range-end').value;if(!start||!end||start>end||new Date(end)-new Date(start)>366*86400000)throw Error('Escolha um intervalo válido de até 366 dias.');range={start,end};await loadPatient(patient.id);}if(action==='export'){const blob=new Blob([JSON.stringify({exported_at:new Date().toISOString(),patient:{full_name:patient.full_name,username:patient.username},records:data.records,diets:data.diets,water:data.water,meals:data.meals,items:data.items,period:range},null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='prontuario-exportado.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Exportação gerada. O arquivo contém dados pessoais e notas privadas.');}}
content.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.action)await applyAction(b.dataset.action);if(b.dataset.tab){selectedTab=b.dataset.tab;renderPatient();}if(b.dataset.openPatient)await openPatient(b.dataset.openPatient);if(b.dataset.review){await reviewClinical(b.dataset.review);toast('Registro revisado.');await refresh();}if(b.dataset.editAnamnesis)anamnesisForm(data.records.find(r=>r.id===b.dataset.editAnamnesis));if(b.dataset.previewDiet)await previewDiet(b.dataset.previewDiet);if(b.dataset.file){const url=await getSignedAttachment(b.dataset.file);const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.click();}if(b.dataset.taskDone){await updateTask(b.dataset.taskDone,{status:'reviewed'});await refresh();}if(b.dataset.taskSnooze){await updateTask(b.dataset.taskSnooze,{status:'snoozed',snoozed_until:new Date(Date.now()+86400000).toISOString()});await refresh();}if(b.dataset.completeAppointment){await query(db.from('appointments').update({status:'completed'}).eq('id',b.dataset.completeAppointment).select());await refresh();}if(b.dataset.cancelAppointment&&confirm('Cancelar esta consulta?')){await query(db.from('appointments').update({status:'cancelled'}).eq('id',b.dataset.cancelAppointment).select());await refresh();}if(b.dataset.toggleTemplate){await query(db.from('checkin_templates').update({active:b.dataset.enabled!=='true'}).eq('id',b.dataset.toggleTemplate).select());await settings();}if(b.dataset.toggleRule){await query(db.from('automation_rules').update({enabled:b.dataset.enabled!=='true'}).eq('id',b.dataset.toggleRule).select());await settings();}if(b.dataset.editRule){automationForm(b.dataset.editRule,JSON.parse(b.dataset.config));}}catch(error){toast(error.message);}});
content.addEventListener('change',e=>{if(e.target.id==='measurement'){const metric=e.target.value;const series=data.records.filter(r=>r.kind==='assessment'&&r.payload.measurements?.[metric]!=null).map(r=>({id:r.id,date:dateKey(new Date(r.occurred_at)),value:Number(r.payload.measurements[metric]),raw:r})).filter(r=>r.date>=range.start&&r.date<=range.end).sort((a,b)=>a.date.localeCompare(b.date));$('#measure-chart').innerHTML=chart(metric,series,'cm');}});
async function init(){try{const auth=await requireAuth({role:'admin'});if(!auth)return;profile=auth.profile;const prefs=await db.from('admin_preferences').select('payload').eq('user_id',profile.user_id).maybeSingle();favorites=new Set(prefs.data?.payload?.favorites||[]);await loadPatients(true);const params=new URLSearchParams(location.search);if(params.has('patient'))await openPatient(params.get('patient'));else await navigate(['overview','patients','agenda','tasks','content','settings'].includes(params.get('view'))?params.get('view'):'overview');}catch(error){errorView(error);}}
init();
function goalForm(){openEditor('Definir meta e objetivo',field('valid_from','Válida a partir de','date',dateKey(),true)+field('water_ml','Meta de hidratação (ml)','number','',true)+area('objective','Objetivo do acompanhamento'),async fd=>{const water=Number(fd.get('water_ml'));if(!Number.isInteger(water)||water<100||water>10000)throw Error('Informe uma meta entre 100 e 10.000 ml.');await query(db.from('patient_goals').insert({patient_id:patient.id,valid_from:fd.get('valid_from'),water_ml:water,objective:fd.get('objective'),created_by:profile.id}).select());});}
function accessForm(){openEditor('Redefinir acesso do paciente',`<p class="notice">Confirme a identidade do paciente antes de definir a senha. Compartilhe o novo acesso somente pelo canal já conhecido. A senha antiga deixará de funcionar.</p>${field('password','Nova senha (mínimo 12 caracteres)','password','',true)}${field('confirmation','Repita a nova senha','password','',true)}<label class="check-field"><input name="verified" type="checkbox" required>Confirmei a identidade do paciente e desejo redefinir sua senha.</label>`,async fd=>{if(fd.get('password').length<12||fd.get('password')!==fd.get('confirmation'))throw Error('As senhas devem ser iguais e ter pelo menos 12 caracteres.');const {data:result,error}=await db.functions.invoke('manage-patient-access',{body:{patient_id:patient.id,new_password:fd.get('password')}});if(error||result?.error)throw Error(result?.error||error.message);if(result?.warning)alert(result.warning);});$('#editor').querySelectorAll('[type=password]').forEach(i=>i.minLength=12);}
function automationForm(id,config){openEditor('Parâmetros da automação',field('hour','Executar a partir desta hora (São Paulo)','number',config.hour??8,true)+select('weekday','Dia da semana',[['','Todos os dias'],['0','Domingo'],['1','Segunda-feira'],['2','Terça-feira'],['3','Quarta-feira'],['4','Quinta-feira'],['5','Sexta-feira'],['6','Sábado']],config.weekday==null?'':String(config.weekday))+field('lookback_days','Período analisado (dias)','number',config.lookback_days??7,true)+'<p class="notice">O servidor verifica as regras a cada 15 minutos. Cada evento é registrado uma única vez. Somente avisos internos são gerados.</p>',async fd=>{const hour=Number(fd.get('hour')),lookback=Number(fd.get('lookback_days'));if(!Number.isInteger(hour)||hour<0||hour>23||!Number.isInteger(lookback)||lookback<1||lookback>90)throw Error('Use hora de 0 a 23 e período de 1 a 90 dias.');await query(db.from('automation_rules').update({config:{...config,hour,weekday:fd.get('weekday')===''?null:Number(fd.get('weekday')),lookback_days:lookback}}).eq('id',id).select());});}
function recordCalendar(){const dates=datesInRange(range.start,range.end);return `<div class="record-calendar">${dates.map(d=>{const categories=[];if(data.water.some(r=>r.log_date===d))categories.push('Água');if(data.meals.some(r=>r.check_date===d)||(data.reports||[]).some(r=>r.report_date===d))categories.push('Refeições');if(data.records.some(r=>dateKey(new Date(r.occurred_at))===d))categories.push('Atualização');return `<div class="calendar-day ${categories.length?'has-record':''}" title="${fmt(d)}: ${categories.join(', ')||'Sem registro'}"><strong>${d.slice(8)}</strong><small>${categories.length?'✓ '+categories.join(' · '):'— Sem registro'}</small></div>`;}).join('')}</div><p class="subtitle">Calendário de registros, sem avaliar comportamento ou adesão clínica.</p>`;}
function waterComparison(){const total=datesInRange(range.start,range.end).length;const previous=data.previousWater||[];const mean=rows=>rows.length?Math.round(rows.reduce((s,r)=>s+Number(r.amount_ml),0)/rows.length).toLocaleString('pt-BR')+' ml':'Sem registro';return `<section class="card"><h2>Comparação com período anterior</h2><p class="subtitle">Média calculada somente nos dias com registros. Coberturas diferentes limitam a comparação.</p><div class="table-wrap"><table><thead><tr><th>Período</th><th>Cobertura</th><th>Média nos dias registrados</th></tr></thead><tbody><tr><td>${fmt(range.start)} a ${fmt(range.end)}</td><td>${data.water.length}/${total} dias</td><td>${mean(data.water)}</td></tr><tr><td>${fmt(subtractDays(range.start,total))} a ${fmt(subtractDays(range.start,1))}</td><td>${previous.length}/${total} dias</td><td>${mean(previous)}</td></tr></tbody></table></div></section>`;}
function templateForm(){openEditor('Novo formulário de check-in',field('name','Nome do formulário','text','Check-in de acompanhamento',true)+`<p class="subtitle">Configure até seis perguntas. Campos sem título não serão incluídos. Escalas vão de 1 a 5.</p>${Array.from({length:6},(_,i)=>`<div class="form-grid">${field('label_'+i,'Pergunta '+(i+1))}${select('type_'+i,'Tipo de resposta',[['text','Texto livre'],['scale','Escala de 1 a 5'],['number','Número']])}<label class="check-field"><input type="checkbox" name="required_${i}">Resposta obrigatória</label></div>`).join('')}`,async fd=>{const fields=[];for(let i=0;i<6;i++){const label=fd.get('label_'+i).trim();if(!label)continue;const type=fd.get('type_'+i);fields.push({key:'question_'+crypto.randomUUID().replaceAll('-',''),label,type,required:fd.has('required_'+i),...(type==='scale'?{min:1,max:5}:{} )});}if(!fields.length)throw Error('Cadastre pelo menos uma pergunta.');await query(db.from('checkin_templates').insert({name:fd.get('name'),fields,active:true,created_by:profile.id}).select());});}
function waterEventTable(){const rows=data.waterEvents||[];return `<section class="card"><h2>Horários dos registros de água</h2><p class="notice">Horário do lançamento, exibido em São Paulo. Os registros antigos não permitem reconstruir horários de consumo. Não inferimos horários ausentes.</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Data do registro</th><th>Horário do lançamento</th><th>Incremento ou correção</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${fmt(r.log_date)}</td><td>${time(r.created_at)}</td><td>${r.delta_ml>0?'+':''}${r.delta_ml} ml</td></tr>`).join('')}</tbody></table></div>`:empty('Sem eventos com horário neste período.')}</section>`;}
function consultationSummary(){const last=data.appointments.filter(a=>a.status==='completed'&&a.starts_at<=new Date().toISOString()).sort((a,b)=>b.starts_at.localeCompare(a.starts_at))[0];const start=last?dateKey(new Date(last.starts_at)):range.start;const records=data.records.filter(r=>dateKey(new Date(r.occurred_at))>=start);const difficulties=records.filter(r=>r.kind==='checkin'&&r.status!=='reviewed'&&(r.payload.difficulty||r.payload.help_requested));const plans=data.diets.filter(d=>dateKey(new Date(d.created_at))>=start);const pending=data.tasks.filter(t=>!['completed','reviewed'].includes(t.status));const registered=data.water.length,days=datesInRange(range.start,range.end).length;return `<section class="card"><h2>Preparação da próxima consulta</h2><p class="subtitle">${last?'Desde a consulta de '+fmt(start):'Desde '+fmt(start)+' (período selecionado)'}. Resumo descritivo dos registros disponíveis.</p><div class="item"><strong>${records.filter(r=>r.kind==='assessment').length} avaliação(ões) · ${records.filter(r=>r.kind==='checkin').length} check-in(s)</strong><div class="item-actions"><button class="secondary" data-tab="assessment">Ver avaliações</button><button class="secondary" data-tab="checkin">Ver relatos</button></div></div><div class="item"><strong>Cobertura de hidratação: ${registered}/${days} dias</strong><p>Fonte: ${fmt(range.start)} a ${fmt(range.end)}. Períodos sem registros permanecem desconhecidos.</p><button class="secondary" data-tab="water">Abrir registros de água</button></div><div class="item"><strong>${plans.length} plano(s) criado(s) no período</strong><div class="item-actions"><button class="secondary" data-tab="plan">Ver versões e datas</button></div></div><div class="item"><strong>Dificuldades ainda não revisadas</strong>${difficulties.length?difficulties.map(r=>`<p>${fmt(r.occurred_at)}: ${esc(r.payload.difficulty||'Paciente pediu ajuda.')}</p>`).join(''):'<p>Nenhuma dificuldade pendente nos relatos consultados.</p>'}<button class="secondary" data-tab="checkin">Abrir fontes</button></div><div class="item"><strong>${pending.length} ação(ões) ou pergunta(s) pendente(s)</strong>${pending.slice(0,5).map(t=>`<p>${esc(t.title)} — ${esc(t.reason||'Sem contexto adicional')}</p>`).join('')}</div></section>`;}
function checkinCharts(records){return [['energy','Energia relatada','1–5'],['sleep_hours','Sono relatado','horas']].map(([key,title,unit])=>{const rows=records.filter(r=>r.kind==='checkin'&&r.payload[key]!==''&&r.payload[key]!=null).map(r=>({date:dateKey(new Date(r.occurred_at)),value:Number(r.payload[key]),id:r.id,raw:{...r,payload:{...r.payload,source:'Autorrelato do check-in'}}})).filter(r=>Number.isFinite(r.value)).sort((a,b)=>a.date.localeCompare(b.date));return rows.length>=2?chart(title,rows,unit):`<section class="card"><h2>${title}</h2>${empty('São necessários pelo menos dois relatos para desenhar a evolução. Consulte os registros individuais abaixo.')}</section>`;}).join('');}
function historyTimeline(){const events=[...data.records.map(r=>({date:r.created_at,html:recordCards([r])})),...data.diets.map(d=>({date:d.created_at,html:`<article class="item"><strong>Plano: ${esc(d.title)}</strong><p>${fmt(d.created_at)} · ${esc(statusNames[d.status]||d.status)}</p><button class="secondary" data-tab="plan">Abrir planos</button></article>`})),...data.appointments.map(a=>({date:a.starts_at,html:`<article class="item"><strong>Consulta · ${esc(statusNames[a.status]||a.status)}</strong><p>${time(a.starts_at)}</p><p>${esc(a.notes||'')}</p></article>`})),...data.tasks.map(t=>({date:t.created_at,html:`<article class="item"><strong>Tarefa: ${esc(t.title)}</strong><p>${time(t.created_at)} · ${esc(statusNames[t.status]||t.status)}</p><p>${esc(t.reason||'')}</p></article>`}))].sort((a,b)=>b.date.localeCompare(a.date));return events.length?events.map(e=>e.html).join(''):empty('O histórico será construído a partir de registros reais.');}
